fn numpy_insert<T>(mut arr: Vec<T>, idx: usize, value: T) -> Vec<T> {
    // Ensure the index is within the valid range [0, arr.len()]
    assert!(idx <= arr.len(), "Insertion index out of bounds");

    // `Vec::insert` shifts all elements at and after `idx` to the right,
    // then places `value` at position `idx`.
    arr.insert(idx, value);

    // Return the newly grown vector
    arr
}

